# 3.2 — Using the compiled Python UI class
# compiled_example.py
#
# This example shows how to use the Python file generated by:
#     pyside6-uic mainwindow.ui -o mainwindow_ui.py
#
# The generated file contains a class called Ui_MainWindow.
# We subclass QMainWindow and mix in Ui_MainWindow to build
# a fully functional window.

# -----------------------------
# IMPORTS
# -----------------------------
import random
import sys

from PySide6.QtCore import Qt
from PySide6.QtWidgets import QApplication, QMainWindow

# Import the generated UI class
from mainwindow_ui import Ui_MainWindow


# -----------------------------
# MAIN WINDOW CLASS
# -----------------------------
# We inherit from both QMainWindow and Ui_MainWindow.
# QMainWindow gives us the window behavior.
# Ui_MainWindow gives us the widgets created in Designer.
class MainWindow(QMainWindow, Ui_MainWindow):
    def __init__(self):
        super().__init__()

        # Build the UI onto this window
        self.setupUi(self)

        # Customize the label (font size + alignment)
        f = self.label.font()
        f.setPointSize(25)
        self.label.setFont(f)

        self.label.setAlignment(
            Qt.AlignmentFlag.AlignHCenter |
            Qt.AlignmentFlag.AlignVCenter
        )

        # Connect the button to our custom slot
        self.pushButton.pressed.connect(self.update_label)

    # -----------------------------
    # SLOT: Update the label text
    # -----------------------------
    def update_label(self):
        n = random.randint(1, 6)
        self.label.setText(f"{n}")


# -----------------------------
# APPLICATION STARTUP
# -----------------------------
app = QApplication(sys.argv)

window = MainWindow()
window.show()

app.exec()
